18	// ─── Thread-local stream override for Green Context SM partitioning ────────
19	
20	thread_local! {
21	    static STREAM_OVERRIDE: Cell<Option<CUstream>> = const { Cell::new(None) };
22	    static PREFILL_STREAM_OVERRIDE: Cell<bool> = const { Cell::new(false) };
23	}
24	
25	/// Scoped stream override for [`active_cu_stream`]; drop restores the previous value.
26	pub struct StreamOverrideGuard {
27	    previous: Option<CUstream>,
28	    previous_prefill: bool,
29	}
30	
31	impl StreamOverrideGuard {
32	    /// # Safety
33	    /// The stream must be valid for the guard's lifetime and belong to the
34	    /// same CUDA device as the `DeviceContext`.
35	    pub unsafe fn activate(stream: CUstream) -> Self {
36	        Self::activate_inner(stream, false)
37	    }
38	
39	    /// # Safety
40	    /// The stream must be valid for the guard's lifetime and belong to the
41	    /// same CUDA device as the `DeviceContext`.
42	    pub unsafe fn activate_prefill(stream: CUstream) -> Self {
43	        Self::activate_inner(stream, true)
44	    }
45	
46	    fn activate_inner(stream: CUstream, prefill: bool) -> Self {
47	        let previous = STREAM_OVERRIDE.with(|c| c.replace(Some(stream)));
48	        let previous_prefill = PREFILL_STREAM_OVERRIDE.with(|c| c.replace(prefill));
49	        Self {
50	            previous,
51	            previous_prefill,
52	        }
53	    }
54	}
55	
56	impl Drop for StreamOverrideGuard {
57	    fn drop(&mut self) {
58	        STREAM_OVERRIDE.with(|c| c.set(self.previous));
59	        PREFILL_STREAM_OVERRIDE.with(|c| c.set(self.previous_prefill));
60	    }
61	}
62	
63	/// Returns true if a stream override is currently active on this thread.
64	pub fn has_stream_override() -> bool {
65	    STREAM_OVERRIDE.with(|c| c.get().is_some())
66	}
67	
68	/// Returns true while split-concurrent prefill owns the stream override.
69	pub fn has_prefill_stream_override() -> bool {
70	    PREFILL_STREAM_OVERRIDE.with(Cell::get)
71	}
72	
73	/// Returns the effective CUDA stream: the thread-local override if set,
74	/// otherwise the context's own stream.
75	#[inline]
76	pub fn active_cu_stream(ctx: &DeviceContext) -> CUstream {
77	    STREAM_OVERRIDE
78	        .with(Cell::get)
79	        .unwrap_or_else(|| ctx.stream.cu_stream())
80	}
81	
82	/// Poll the active stream up to a fixed cap, then synchronize that stream.
83	const STREAM_SPIN_WAIT_CAP: std::time::Duration = std::time::Duration::from_millis(5);
84	
85	pub fn stream_spin_wait(ctx: &DeviceContext) -> anyhow::Result<()> {
86	    let stream = active_cu_stream(ctx);
87	    let cap = std::time::Instant::now() + STREAM_SPIN_WAIT_CAP;
88	    loop {
89	        match unsafe { cudarc::driver::sys::cuStreamQuery(stream) } {
90	            cudarc::driver::sys::CUresult::CUDA_SUCCESS => return Ok(()),
91	            cudarc::driver::sys::CUresult::CUDA_ERROR_NOT_READY => {
92	                if std::time::Instant::now() >= cap {
93	                    let result = unsafe { cudarc::driver::sys::cuStreamSynchronize(stream) };
94	                    anyhow::ensure!(
95	                        result == cudarc::driver::sys::CUresult::CUDA_SUCCESS,
96	                        "stream sync after spin cap failed: {result:?}"
97	                    );
98	                    return Ok(());
99	                }
100	                std::hint::spin_loop();
101	            }
102	            err => return Err(anyhow::anyhow!("cuStreamQuery failed: {err:?}")),
103	        }
104	    }
105	}
