107	/// Copy token ids from an i32 argmax buffer into a u32 embedding buffer.
108	pub fn memcpy_dtod_u32_from_i32(
109	    ctx: &DeviceContext,
110	    src: &CudaSlice<i32>,
111	    dst: &mut CudaSlice<u32>,
112	    count: usize,
113	) -> anyhow::Result<()> {
114	    use cudarc::driver::DevicePtr;
115	    use cudarc::driver::DevicePtrMut;
116	
117	    anyhow::ensure!(
118	        !has_stream_override(),
119	        "dtod i32->u32 copy runs on the base stream only"
120	    );
121	    anyhow::ensure!(
122	        count <= src.len() && count <= dst.len(),
123	        "dtod i32->u32 copy of {count} exceeds src {} or dst {}",
124	        src.len(),
125	        dst.len()
126	    );
127	    if count == 0 {
128	        return Ok(());
129	    }
130	    let (src_ptr, _src_guard) = src.device_ptr(&ctx.stream);
131	    let (dst_ptr, _dst_guard) = dst.device_ptr_mut(&ctx.stream);
132	    let result = unsafe {
133	        cudarc::driver::sys::cuMemcpyDtoDAsync_v2(
134	            dst_ptr,
135	            src_ptr,
136	            count * std::mem::size_of::<i32>(),
137	            ctx.stream.cu_stream(),
138	        )
139	    };
140	    anyhow::ensure!(
141	        result == cudarc::driver::sys::CUresult::CUDA_SUCCESS,
142	        "cuMemcpyDtoDAsync i32->u32 failed: {result:?}"
143	    );
144	    Ok(())
145	}
