348	/// CUDA device context holding context and stream.
349	#[derive(Clone)]
350	pub struct DeviceContext {
351	    pub ctx: Arc<CudaContext>,
352	    pub stream: Arc<CudaStream>,
353	    pub device_ordinal: usize,
354	}
355	
356	impl DeviceContext {
357	    pub fn new() -> Result<Self> {
358	        Self::new_with_device(0)
359	    }
360	
361	    pub fn new_with_device(device_ordinal: usize) -> Result<Self> {
362	        unsafe {
363	            let err = ffi::cuda_set_device(device_ordinal as i32);
364	            if err != 0 {
365	                return Err(anyhow!(
366	                    "Failed to set CUDA device {}: cudaError={}",
367	                    device_ordinal,
368	                    err
369	                ));
370	            }
371	        }
372	        let ctx = CudaContext::new(device_ordinal)
373	            .map_err(|e| anyhow!("Failed to create CUDA context: {}", e))?;
374	
375	        // Disable multi-stream event tracking before creating streams.
376	        // We use a single compute stream, so no cross-stream synchronization is needed.
377	        // This avoids stream.wait(event) calls that break CUDA Graph capture.
378	        // SAFETY: We only use one stream for all GPU work.
379	        unsafe {
380	            ctx.disable_event_tracking();
381	        }
382	
383	        let stream = ctx
384	            .new_stream()
385	            .map_err(|e| anyhow!("Failed to create CUDA stream: {}", e))?;
386	
387	        // Initialize cuBLAS handle
388	        unsafe {
389	            ffi::cublas_init();
390	        }
391	
392	        Ok(Self {
393	            ctx,
394	            stream,
395	            device_ordinal,
396	        })
397	    }
398	
399	    /// Synchronize stream
400	    pub fn sync(&self) -> Result<()> {
401	        self.stream
402	            .synchronize()
403	            .map_err(|e| anyhow!("Sync failed: {}", e))
404	    }
405	}
