407	/// 1D device tensor (vector) — stored as bf16.
408	pub struct DeviceVec {
409	    pub data: CudaSlice<bf16>,
410	    pub len: usize,
411	}
412	
413	impl DeviceVec {
414	    /// Create from host data (bf16)
415	    pub fn from_host(ctx: &DeviceContext, data: &[bf16]) -> Result<Self> {
416	        let gpu_data = ctx
417	            .stream
418	            .clone_htod(data)
419	            .map_err(|e| anyhow!("H2D copy failed: {}", e))?;
420	        Ok(Self {
421	            data: gpu_data,
422	            len: data.len(),
423	        })
424	    }
425	
426	    #[allow(clippy::cast_ptr_alignment)]
427	    pub fn from_safetensors(ctx: &DeviceContext, data: &[u8]) -> Result<Self> {
428	        if !data.len().is_multiple_of(2) {
429	            return Err(anyhow!(
430	                "Data length must be even for bf16: got {} bytes",
431	                data.len()
432	            ));
433	        }
434	        let len = data.len() / 2;
435	        // NOTE: This assumes a little-endian host. Safetensors are little-endian.
436	        // On a big-endian machine, this will be incorrect. A full solution would
437	        // involve byte-swapping.
438	        let slice = unsafe { std::slice::from_raw_parts(data.as_ptr().cast::<bf16>(), len) };
439	        Self::from_host(ctx, slice)
440	    }
441	
442	    /// Create zeroed tensor
443	    pub fn zeros(ctx: &DeviceContext, len: usize) -> Result<Self> {
444	        let gpu_data: CudaSlice<bf16> = ctx
445	            .stream
446	            .alloc_zeros(len)
447	            .map_err(|e| anyhow!("Alloc failed: {}", e))?;
448	        Ok(Self {
449	            data: gpu_data,
450	            len,
451	        })
452	    }
453	
454	    /// Copy to host as f32.
455	    pub fn to_host(&self, ctx: &DeviceContext) -> Result<Vec<f32>> {
456	        let host_f16 = ctx
457	            .stream
458	            .clone_dtoh(&self.data)
459	            .map_err(|e| anyhow!("D2H copy failed: {}", e))?;
460	        ctx.sync()?;
461	        Ok(host_f16.iter().map(|x| x.to_f32()).collect())
462	    }
463	}
464	
465	impl Clone for DeviceVec {
