474	/// 2D device tensor (matrix) — stored in row-major order as bf16.
475	pub struct DeviceMatrix {
476	    pub data: CudaSlice<bf16>,
477	    pub rows: usize,
478	    pub cols: usize,
479	}
480	
481	impl DeviceMatrix {
482	    /// Vertically stack matrices (same cols, concatenate rows). GPU D2D copy.
483	    pub fn vstack(ctx: &DeviceContext, matrices: &[&DeviceMatrix]) -> Result<Self> {
484	        assert!(!matrices.is_empty());
485	        let cols = matrices[0].cols;
486	        for m in matrices {
487	            assert_eq!(m.cols, cols, "vstack: all matrices must have same cols");
488	        }
489	        let total_rows: usize = matrices.iter().map(|m| m.rows).sum();
490	        let mut data: CudaSlice<bf16> = ctx
491	            .stream
492	            .alloc_zeros(total_rows * cols)
493	            .map_err(|e| anyhow!("vstack alloc failed: {}", e))?;
494	        let mut offset = 0;
495	        for m in matrices {
496	            let n = m.rows * m.cols;
497	            let src = m.data.slice(..n);
498	            let mut dst = data.slice_mut(offset..offset + n);
499	            ctx.stream
500	                .memcpy_dtod(&src, &mut dst)
501	                .map_err(|e| anyhow!("vstack D2D copy failed: {}", e))?;
502	            offset += n;
503	        }
504	        Ok(Self {
505	            data,
506	            rows: total_rows,
507	            cols,
508	        })
509	    }
510	
511	    /// Create from host data (row-major, bf16)
512	    pub fn from_host(ctx: &DeviceContext, data: &[bf16], rows: usize, cols: usize) -> Result<Self> {
513	        assert_eq!(data.len(), rows * cols);
514	        let gpu_data = ctx
515	            .stream
516	            .clone_htod(data)
517	            .map_err(|e| anyhow!("H2D copy failed: {}", e))?;
518	        Ok(Self {
519	            data: gpu_data,
520	            rows,
521	            cols,
522	        })
523	    }
524	
525	    #[allow(clippy::cast_ptr_alignment)]
526	    pub fn from_safetensors(
527	        ctx: &DeviceContext,
528	        data: &[u8],
529	        rows: usize,
530	        cols: usize,
531	    ) -> Result<Self> {
532	        if data.len() != rows * cols * std::mem::size_of::<bf16>() {
533	            return Err(anyhow!(
534	                "Data length mismatch: expected {} bytes, got {} bytes",
535	                rows * cols * std::mem::size_of::<bf16>(),
536	                data.len()
537	            ));
538	        }
539	        // NOTE: This assumes a little-endian host. Safetensors are little-endian.
540	        // On a big-endian machine, this will be incorrect. A full solution would
541	        // involve byte-swapping.
542	        let slice =
543	            unsafe { std::slice::from_raw_parts(data.as_ptr().cast::<bf16>(), rows * cols) };
544	        Self::from_host(ctx, slice, rows, cols)
545	    }
546	}
