548	/// Batched hidden states: seq_len vectors of dim hidden_dim, stored contiguously.
549	/// Memory layout: [hidden_dim * seq_len] elements, token i at offset i * hidden_dim.
550	/// cuBLAS interprets as [hidden_dim, seq_len] column-major.
551	pub struct HiddenStates {
552	    pub data: CudaSlice<bf16>,
553	    pub hidden_dim: usize,
554	    pub seq_len: usize,
555	}
556	
557	impl HiddenStates {
558	    pub fn as_ref(&self) -> HiddenStatesRef<'_> {
559	        HiddenStatesRef {
560	            data: &self.data,
561	            hidden_dim: self.hidden_dim,
562	            seq_len: self.seq_len,
563	        }
564	    }
565	
566	    /// Logical extent `hidden_dim * seq_len`, checked to fit the backing
567	    /// allocation (`>=`, not `==`: buffers allocate at a max and rewrite
568	    /// `seq_len` to the active size per step). Fields are public, so a safe
569	    /// caller can shape a logical size past the backing; launch wrappers
570	    /// call this to reject that before it reaches a kernel.
571	    pub(crate) fn checked_extent(&self, what: &str) -> Result<usize> {
572	        let extent = self
573	            .hidden_dim
574	            .checked_mul(self.seq_len)
575	            .ok_or_else(|| anyhow!("{what} logical extent overflow"))?;
576	        if self.data.len() < extent {
577	            return Err(anyhow!(
578	                "{what} backing len {} < hidden_dim {} * seq_len {}",
579	                self.data.len(),
580	                self.hidden_dim,
581	                self.seq_len
582	            ));
583	        }
584	        Ok(extent)
585	    }
586	
587	    /// Create zeroed batch
588	    pub fn zeros(ctx: &DeviceContext, hidden_dim: usize, seq_len: usize) -> Result<Self> {
589	        let data: CudaSlice<bf16> = ctx
590	            .stream
591	            .alloc_zeros(hidden_dim * seq_len)
592	            .map_err(|e| anyhow!("Alloc failed: {}", e))?;
593	        Ok(Self {
594	            data,
595	            hidden_dim,
596	            seq_len,
597	        })
598	    }
599	
600	    /// Create from host data: `hidden_dim * seq_len` bf16, token `i` at `i * hidden_dim`.
601	    pub fn from_host(
602	        ctx: &DeviceContext,
603	        data: &[bf16],
604	        hidden_dim: usize,
605	        seq_len: usize,
606	    ) -> Result<Self> {
607	        assert_eq!(data.len(), hidden_dim * seq_len);
608	        let gpu_data = ctx
609	            .stream
610	            .clone_htod(data)
611	            .map_err(|e| anyhow!("H2D copy failed: {}", e))?;
612	        Ok(Self {
613	            data: gpu_data,
614	            hidden_dim,
615	            seq_len,
616	        })
617	    }
618	
619	    /// Copy to host as f32. bf16 → f32 is lossless, so f32 equality is bitwise.
620	    pub fn to_host(&self, ctx: &DeviceContext) -> Result<Vec<f32>> {
621	        let host = ctx
622	            .stream
623	            .clone_dtoh(&self.data)
624	            .map_err(|e| anyhow!("D2H copy failed: {}", e))?;
625	        ctx.sync()?;
626	        Ok(host.iter().map(|x| x.to_f32()).collect())
627	    }
628	}
