630	// ── Typed tensor layer ───────────────────────────────────────────────
631	//
632	// `GpuTensor<DIM>` encodes the hidden dimension in the type. The seq_len
633	// (batch) axis stays runtime because it changes per step. Weight matrices
634	// carry both dimensions: `GpuWeight<OUT, IN>`.
635	//
636	// These are additive — existing `HiddenStates`/`DeviceMatrix` stay untouched.
637	// Model crates migrate one at a time.
638	
639	/// Batched bf16 activation tensor with compile-time hidden dimension.
640	///
641	/// Memory layout: `[DIM * seq_len]` contiguous bf16, token `i` at `i * DIM`.
642	/// cuBLAS sees `[DIM, seq_len]` column-major.
643	pub struct GpuTensor<const DIM: usize> {
644	    pub data: CudaSlice<bf16>,
645	    pub seq_len: usize,
646	}
647	
648	impl<const DIM: usize> GpuTensor<DIM> {
649	    pub fn zeros(ctx: &DeviceContext, seq_len: usize) -> Result<Self> {
650	        let data: CudaSlice<bf16> = ctx
651	            .stream
652	            .alloc_zeros(DIM * seq_len)
653	            .map_err(|e| anyhow!("GpuTensor<{}>::zeros alloc failed: {}", DIM, e))?;
654	        Ok(Self { data, seq_len })
655	    }
656	
657	    pub fn from_device_matrix_rows(m: DeviceMatrix) -> Result<Self> {
658	        anyhow::ensure!(
659	            m.cols == DIM,
660	            "GpuTensor<{}>::from_device_matrix_rows col mismatch: got {}",
661	            DIM,
662	            m.cols,
663	        );
664	        Ok(Self {
665	            data: m.data,
666	            seq_len: m.rows,
667	        })
668	    }
669	}
670	
671	/// bf16 weight matrix with compile-time dimensions: `[OUT, IN]` row-major.
672	pub struct GpuWeight<const OUT: usize, const IN: usize> {
673	    pub(crate) data: CudaSlice<bf16>,
674	}
675	
676	impl<const OUT: usize, const IN: usize> GpuWeight<OUT, IN> {
677	    pub fn from_device_matrix(m: DeviceMatrix) -> Result<Self> {
678	        anyhow::ensure!(
679	            m.rows == OUT && m.cols == IN,
680	            "GpuWeight<{}, {}>::from_device_matrix shape mismatch: got [{}, {}]",
681	            OUT,
682	            IN,
683	            m.rows,
684	            m.cols,
685	        );
686	        Ok(Self { data: m.data })
687	    }
688	}
689	
690	/// bf16 RMSNorm weight vector with compile-time dimension.
691	pub struct NormWeight<const DIM: usize> {
692	    pub data: CudaSlice<bf16>,
693	}
694	
695	impl<const DIM: usize> NormWeight<DIM> {
696	    pub fn from_device_vec(v: DeviceVec) -> Result<Self> {
697	        anyhow::ensure!(
698	            v.len == DIM,
699	            "NormWeight<{}>::from_device_vec len mismatch: got {}",
700	            DIM,
701	            v.len,
702	        );
703	        Ok(Self { data: v.data })
704	    }
705	}
706	
707	/// f32 raw buffer with compile-time element count per batch entry.
708	pub struct GpuRawSlice<const ELEMS: usize> {
709	    pub data: CudaSlice<f32>,
710	    pub batch_size: usize,
711	}
712	
713	impl<const ELEMS: usize> GpuRawSlice<ELEMS> {
714	    pub fn zeros(ctx: &DeviceContext, batch_size: usize) -> Result<Self> {
715	        let data: CudaSlice<f32> = ctx
716	            .stream
717	            .alloc_zeros(ELEMS * batch_size)
718	            .map_err(|e| anyhow!("GpuRawSlice<{}>::zeros alloc failed: {}", ELEMS, e))?;
719	        Ok(Self { data, batch_size })
720	    }
721	}
722	
723	/// i32 raw buffer with compile-time element count per batch entry.
724	pub struct GpuRawSliceI32<const ELEMS: usize> {
725	    pub data: CudaSlice<i32>,
726	    pub batch_size: usize,
727	}
728	
729	impl<const ELEMS: usize> GpuRawSliceI32<ELEMS> {
730	    pub fn zeros(ctx: &DeviceContext, batch_size: usize) -> Result<Self> {
731	        let data: CudaSlice<i32> = ctx
732	            .stream
733	            .alloc_zeros(ELEMS * batch_size)
734	            .map_err(|e| anyhow!("GpuRawSliceI32<{}>::zeros alloc failed: {}", ELEMS, e))?;
735	        Ok(Self { data, batch_size })
736	    }
737	}
738	
739	/// Non-owning reference to `HiddenStates`-shaped data (bridge to untyped ops).
740	#[derive(Clone, Copy)]
741	pub struct HiddenStatesRef<'a> {
742	    pub data: &'a CudaSlice<bf16>,
743	    pub hidden_dim: usize,
744	    pub seq_len: usize,
745	}
746	
747	#[cfg(test)]
748	mod tests {
749	    use super::*;
750	
751	    #[test]
752	    fn stream_override_guard_restores_on_drop() {
753	        let outer = 0x10usize as CUstream;
754	        assert!(!has_stream_override());
755	        assert!(!has_prefill_stream_override());
756	        {
757	            let _outer_guard = unsafe { StreamOverrideGuard::activate_prefill(outer) };
758	            assert!(has_prefill_stream_override());
759	            {
760	                let _inner_guard = unsafe { StreamOverrideGuard::activate(0x20usize as CUstream) };
761	                assert!(!has_prefill_stream_override());
762	            }
763	            assert_eq!(STREAM_OVERRIDE.with(Cell::get), Some(outer));
764	            assert!(has_prefill_stream_override());
765	        }
766	        assert!(!has_stream_override());
767	        assert!(!has_prefill_stream_override());
768	    }
769	
770	    fn copy_matrix_to_host(ctx: &DeviceContext, matrix: &DeviceMatrix) -> Vec<bf16> {
771	        let host = ctx
772	            .stream
773	            .clone_dtoh(&matrix.data)
774	            .expect("D2H copy failed");
775	        ctx.sync().expect("CUDA sync failed");
776	        host
777	    }
