779	    #[test]
780	    fn test_device_matrix_from_safetensors_matches_from_host() {
781	        let ctx = DeviceContext::new().expect("Failed to create CUDA context");
782	        let rows = 3;
783	        let cols = 2;
784	        let host = vec![
785	            bf16::from_f32(-8.0),
786	            bf16::from_f32(-0.25),
787	            bf16::from_f32(1.0),
788	            bf16::from_f32(3.5),
789	            bf16::from_f32(9.0),
790	            bf16::from_f32(10.75),
791	        ];
792	        let safetensor_bytes: Vec<u8> = host
793	            .iter()
794	            .flat_map(|v| v.to_bits().to_le_bytes())
795	            .collect();
796	
797	        let from_host =
798	            DeviceMatrix::from_host(&ctx, &host, rows, cols).expect("from_host should succeed");
799	        let from_safetensors = DeviceMatrix::from_safetensors(&ctx, &safetensor_bytes, rows, cols)
800	            .expect("from_safetensors should succeed");
801	
